  const S={workspace:null,base:null,draft:null,preview:null,dirty:false,busy:false,conflict:false,view:'machine',selected:new Map(),waiting:[],page:1,total:0,picker:null,pickerPage:1,pickerTotal:0,editor:null,recipe:null,editorItems:[],editorBindings:[],editorStages:[],stopRun:null,stopVersion:null,keys:new Map(),editors:new Map()};
  const runLabel=(id)=>{const r=S.editors.get(id)||S.workspace?.result.jobs.find(j=>j.run_id===id);return S.workspace?.run_labels?.[id]||r?.official_code||(r?.release_state==='legacy'?'LSX cũ — chưa xác nhận':'Chưa phát hành');}; const labels={automatic:'Định hình tự động · Cắt liền',semi_automatic:'Định hình bán tự động',cutting:'Cắt',edge:'Ép biên'};
  const statuses={enough:'Đủ nhựa giữ',partial:'Có một phần',none:'Chưa có nhựa',unknown:'Chưa xác định'};
