    if(!response.ok){const detail=data.detail,context=detail&&typeof detail==='object'&&!Array.isArray(detail)?['run_id','order_line_id','stage','machine_id','field'].filter(k=>detail[k]).map(k=>k+': '+detail[k]).join(' · '):'';const e=Error(typeof detail==='string'?detail:Array.isArray(detail)?detail.map(x=>(x.loc||[]).join('.')+': '+x.msg).join('\n'):(detail?.message||JSON.stringify(detail))+(context?'\n'+context:''));e.status=response.status;e.detail=detail;throw e;}return data;
