  async function guard(fn,target){if(S.busy)return;S.busy=true;controls();try{return await fn();}catch(e){const errorTarget=target||([...document.querySelectorAll('dialog[open] .error')].at(-1));if(errorTarget)errorTarget.textContent=e.message;message(e.message,true);if(e.status===409&&e.detail?.code!=='CONFIRMATION_REQUIRED'&&/thay đổi|phiên bản|tính thử lại|Tải lại|Mã thao tác/i.test(e.message)){S.conflict=true;S.preview=null;$('conflict').hidden=false;}}finally{S.busy=false;controls();}}
