  function input(label,value,onchange,{min=0,step='any',type='number',required=true,raw=false}={}){const l=node('label',label),i=node('input');i.type=type;i.required=required;i.value=value??'';if(type==='number'){i.min=min;i.step=step;}i.oninput=()=>onchange(!raw&&type==='number'&&i.value!==''?Number(i.value):i.value);l.append(i);return l;}
