  function renderBindings(){$('runMaterials').replaceChildren();for(const b of S.editorBindings){const row=node('div',undefined,'material-row');row.append(node('span',`${b.order_line_id} · ${b.receipt_id||b.allocation_id} · giữ ${fmt(b.held_kg)} kg`),input('Kg bố trí (0 = bỏ)',b.kg,v=>b.kg=String(v),{step:'0.00000001',raw:true}));$('runMaterials').append(row);}if(!S.editorBindings.length)$('runMaterials').textContent='Chưa có phân bổ. Mở Chuẩn bị nhựa để giữ nguồn trước, rồi tải lại CTĐH.';}
