  function routeStages(){const existing=new Map(S.editorStages.map(s=>[s.order_line_id+':'+s.stage,s]));const next=[];for(const item of S.editorItems){const template=S.recipe?.items.find(i=>i.product_id===item.product_id);const route=template?.snapshot?.route||item.snapshot?.route||[];for(const stage of route.filter(s=>['cutting','edge'].includes(s))){next.push(existing.get(item.order_line_id+':'+stage)||{order_line_id:item.order_line_id,stage,machine_id:null,seconds_per_unit:'',setup_minutes:0,wait_minutes:0,unit:item.unit||item.snapshot?.unit||template?.snapshot.unit,mode:'all',handoff_quantity:null,handoff_quantities:[],hold_machine_while_waiting:false});}}S.editorStages=next;renderStages();}
