  $('moveRun').onclick=()=>guard(async()=>{const target=field(form,'machine_id').value;if(target===S.editor.machine_id)throw Error('Chọn máy đích khác trước.');if(form.reportValidity())await applyEditor();});$('reorderUp').onclick=()=>guard(()=>reorder(S.editor.id,-1));$('reorderDown').onclick=()=>guard(()=>reorder(S.editor.id,1));
  $('removeRun').onclick=()=>guard(async()=>{const id=S.editor.id;if(!await ask('Gỡ lần chạy khỏi lịch?',runLabel(id)+' sẽ về chờ xếp; không xóa lệnh, thực tế hoặc phần giữ nhựa.'))return;if(S.editor.isNew){S.draft.changes=S.draft.changes.filter(c=>c.config.id!==id);S.editors.delete(id);}else if(!S.draft.unschedule.includes(id))S.draft.unschedule.push(id);S.draft.order=S.draft.order.filter(r=>r!==id);S.draft.jobs=S.draft.jobs.filter(j=>j.run_id!==id);S.draft.moves=S.draft.moves.filter(m=>m.run_id!==id);S.draft.changes=S.draft.changes.filter(c=>c.config.id!==id);$('editor').close();touch();});
  $('stopForm').onsubmit=e=>{e.preventDefault();guard(async()=>{const f=$('stopForm'),id=field(f,'id').value;const minutes=field(f,'minutes').value;const patch={id,run_id:S.stopRun,version:S.stopVersion,at:zoned(field(f,'at').value),duration_seconds:minutes===''?null:Math.round(Number(minutes)*60),hold_machine:field(f,'hold_machine').checked,enabled:field(f,'enabled').checked,note:field(f,'note').value};S.draft.stops=S.draft.stops.filter(s=>s.id!==id);S.draft.stops.push(patch);$('stop').close();touch('Dừng/nghỉ đã vào bản nháp. Bấm Tính thử để xem phần bị ảnh hưởng.');},$('stopError'));};
  $('preview').onclick=()=>guard(tryPreview);$('save').onclick=()=>guard(save);$('cancel').onclick=()=>guard(async()=>{if(await ask('Hủy thay đổi?','Bỏ toàn bộ thay đổi chưa lưu và trở lại bản đã tải.')){setWorkspace(clone(S.base),true);message('Đã hủy bản nháp.');}});
  for(const [id,view]of [['byMachine','machine'],['byLine','line']])$(id).onclick=()=>{S.view=view;$('byMachine').setAttribute('aria-pressed',String(view==='machine'));$('byLine').setAttribute('aria-pressed',String(view==='line'));render();};$('zoom').onchange=render;
  $('period').onclick=()=>{field($('periodForm'),'start').value=localValue(S.draft.start);field($('periodForm'),'end').value=localValue(S.draft.end);$('periodDialog').showModal();};$('periodForm').onsubmit=e=>{e.preventDefault();S.draft.start=zoned(field($('periodForm'),'start').value);S.draft.end=zoned(field($('periodForm'),'end').value);$('periodDialog').close();touch('Đã đổi kỳ tính. Backend sẽ kiểm tra lại toàn bộ phần lịch tương lai.');$('horizon').textContent='Kỳ tính nháp: '+dateText(S.draft.start)+' → '+dateText(S.draft.end);};
