  const pager=node('div',undefined,'inline');pager.id='linePager';pager.hidden=true;const prev=btn('← CTĐH',async()=>{S.linePage--;render();});prev.id='linePrev';const count=node('span');count.id='lineCount';const next=btn('CTĐH →',async()=>{S.linePage++;render();});next.id='lineNext';pager.append(prev,count,next);$('gantt').before(pager);
